package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Consolidated duplicate check: rejects a create request whose whole {@link IdentityKey} equals an
 * existing owner's, so a full identity collision is a 409 via {@link DuplicateIdentityException}.
 * Because the telephone is part of the key, two members of the same household with different
 * telephones have different keys and are both allowed.
 */
public class EnsureUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = IdentityKey.of(ownerMapper.toOwner(request));
        for (Owner owner : ownerRepository.findAll()) {
            if (identityKey.equals(IdentityKey.of(owner))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}

